/*
 * A319970  a(n) = A003146(A003144(n)).
 * https://oeis.org/A319970
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1) = 4; for n > 1, a(n) = 4 + Σ_{k=1}^{n-1} d(k), where d(k)
 *            is the tribonacci word on the alphabet {13,11,7}. The tribonacci
 *            word is generated by the morphism: a → a b b → a c c → a
 *            (letters are 'a','b','c') Thus d(k) = 13 if the k‑th letter is
 *            'a', 11 if 'b', 7 if 'c'
 * Range:     u8 n <= 22, u16 n <= 5726, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* n is guaranteed to be ≥ 1 by the build. */
    if (n == 1U)
        return (seq_t)4;

    /* Need the first n−1 letters of the tribonacci word. */
    size_t target = (size_t)(n - 1);

    /* Dynamically grow a buffer holding the current word.  Each
       expansion can at most double the length: a→ab, b→ac (2),
       c→a (1).  Allocate the initial word. */
    char *curr = (char *)malloc(1);
    if (!curr)
        return (seq_t)0;           /* allocation failure */
    curr[0] = 'a';
    size_t curr_len = 1;

    /* Expand until we have enough letters. */
    while (curr_len < target)
    {
        /* The new word will not exceed curr_len*2 characters. */
        size_t new_len = 0;
        char *next = (char *)malloc(curr_len * 2);
        if (!next)
        {
            free(curr);
            return (seq_t)0;
        }

        for (size_t i = 0; i < curr_len; ++i)
        {
            char c = curr[i];
            if (c == 'a')
            {
                next[new_len++] = 'a';
                next[new_len++] = 'b';
            }
            else if (c == 'b')
            {
                next[new_len++] = 'a';
                next[new_len++] = 'c';
            }
            else            /* c == 'c' */
            {
                next[new_len++] = 'a';
            }
        }

        free(curr);
        curr = next;
        curr_len = new_len;
    }

    /* Compute the sum of the first target letter values. */
    seq_t sum = 0;
    for (size_t i = 0; i < target; ++i)
    {
        char c = curr[i];
        if (c == 'a')
            sum += (seq_t)13;
        else if (c == 'b')
            sum += (seq_t)11;
        else                /* c == 'c' */
            sum += (seq_t)7;
    }
    free(curr);

    return (seq_t)4 + sum;
}
